#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto op = [&](int x, int y){
        assert(x>=0 && y>=0 && x+y<n && x+y>0);
        ops.push_back({x,y});
        vector<int> np(n);
        // [C|B|A]: C=p[n-y..n-1], B=p[x..n-y-1], A=p[0..x-1]
        int idx=0;
        for(int i=n-y;i<n;i++) np[idx++]=p[i];
        for(int i=x;i<n-y;i++) np[idx++]=p[i];
        for(int i=0;i<x;i++) np[idx++]=p[i];
        p=np;
    };

    for(int t=0; t<n-1; t++){
        // Find position of value t+1
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;

        // Move value (t+1) from pos to position t
        // Step 1: bring it to position n-1
        if(pos!=n-1){
            // x=pos+1, y=n-1-pos: x+y=n, not valid
            // x=pos, y=n-1-pos: x+y=n-1<n (valid if n-1>0). Element at pos goes to... it's in A (i<x=pos? no, i=pos not < pos). i=pos, x=pos, n-y=pos+1. So pos>=x and pos<n-y, middle. New pos = y+(pos-x)= (n-1-pos)+0 = n-1-pos. Not n-1 unless pos=0.
            // x=pos+1, y=n-2-pos: x+y=n-1<n (valid if pos<=n-3). elem at pos: pos<x=pos+1, so in A. New pos = (n-x)+pos = n-pos-1+pos=n-1. 
            if(pos<=n-3){
                op(pos+1, n-2-pos);
            } else { // pos==n-2
                op(1,1); // rotate: moves n-1 to front, 0 to end
                for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
                if(pos!=n-1 && pos<=n-3) op(pos+1, n-2-pos);
                for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
            }
        }
        if(p[t]==t+1) continue;
        // Now element is at n-1. Bring to position t.
        // x=n-1-t, y=1: x+y=n-t<n (valid if t>0). Elem at n-1: in C(i>=n-1). New pos=i-(n-1)=0. Not t.
        // x=n-1-t, y=0 won't move. Use: x=0, y=n-1-t: elem at n-1 in C. new pos = (n-1)-(n-(n-1-t))=(n-1)-(t+1)=n-2-t. Hmm.
        // x=0,y=n-t: new pos of n-1 = n-1-(t)=... let me just: op(n-1-t,1) puts elem at pos 0, then op(t,0)... 
        if(t==0){ op(0, 1); }
        else { op(n-1-t, 1); op(t, 0); }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
